INSERT INTO patriarchs (id, name_ar, name_en, papal_number, birth_date, death_date, papacy_start, papacy_end, century, short_bio_ar, biography_ar, historical_background_ar, faith_defense_ar, challenges_ar, contributions_ar, image_url, image_source, image_credit)
VALUES
('a0000001-0000-0000-0000-000000000001',
 'القديس مرقس الرسول', 'Saint Mark the Apostle', 1,
 'غير معروف تماماً', 'حوالي 68 م', 'حوالي 42 م', 'حوالي 68 م', 1,
 'أول باباوات كرسي الإسكندرية وأساس الكنيسة القبطية الأرثوذكسية، تلميذ القديس بطرس الرسول وكاتب الإنجيل الثاني.',
 'القديس مرقس هو مؤسس كنيسة الإسكندرية وأول بطاركتها. وُلد في برية الخماسية من أبوين يهوديين، وكان تلميذاً للقديس بطرس الرسول. يُنسب إليه الإنجيل الثاني في العهد الجديد. جاء إلى الإسكندرية في منتصف القرن الأول الميلادي وبشرّ بالمسيحية هناك، وأسس مدرسة الإسكندرية اللاهوتية وكهنوت الكنيسة المصرية. استشهد في عيد القيامة سنة 68 م تقريباً على يد الوثنيين الذين حاولوا إجباره على التخلي عن إيمانه بالمسيح.',
 'كانت الإسكندرية في القرن الأول مركزاً عظيماً للثقافة الهلنستية والفكر الوثني، بها أكبر مكتبة في العالم القديم ومعبد سيرابيس الشهير. كانت المدينة ملتقى للفلاسفة والعلماء من كل أنحاء العالم المعروف آنذاك. دخول المسيحية إلى هذه المدينة كان حدثاً جوهرياً في تاريخ العالم.',
 'أسس القديس مرقس كنيسة الإسكندرية على أساس الإيمان بالمسيح ابن الله المتجسد، وبشّر بالإنجيل في مدينة كانت معقل الوثنية والفلسفة اليونانية. بإنشائه مدرسة الإسكندرية اللاهوتية، وضع الأساس للدفاع العقائدي الذي اشتهرت به الكنيسة القبطية عبر القرون.',
 'واجه القديس مرقس معارضة شديدة من الوثنيين في الإسكندرية، وقد انتهت خدمته بالاستشهاد على يد الحشود الوثنية التي جرّته في شوارع المدينة. التحدي الأكبر كان نشر الإيمان المسيحي في مدينة كانت معقلاً للفكر الوثني.',
 'تأسيس كنيسة الإسكندرية، تأسيس مدرسة الإسكندرية اللاهوتية (أقدم مدرسة لاهوتية مسيحية)، كتابة إنجيل مرقس، وضع أساس الكهنوت القبطي.',
 '', '', '')
ON CONFLICT (papal_number) DO NOTHING;

INSERT INTO patriarchs (id, name_ar, name_en, papal_number, birth_date, death_date, papacy_start, papacy_end, century, short_bio_ar, biography_ar, historical_background_ar, faith_defense_ar, challenges_ar, contributions_ar, image_url, image_source, image_credit)
VALUES
('a0000001-0000-0000-0000-000000000002',
 'البابا أثناسيوس الرسولي', 'Pope Athanasius the Apostolic', 20,
 'حوالي 296 م', '2 مايو 373 م', 'حوالي 328 م', '2 مايو 373 م', 4,
 'البابا العشرون، عمود الدين والمدافع الأول عن ألوهية المسيح ضد بدعة آريوس، عُرف بـ"أثناسيوس ضد العالم".',
 'وُلد القديس أثناسيوس في الإسكندرية. ترهب في سن مبكرة وأصبح شماساً ثم سكرتيراً للبابا ألكسندروس التاسع عشر. رافق معلمه في مجمع نيقية سنة 325 م حيث لعب دوراً بارزاً في إدانة بدعة آريوس. اختير بابا للإسكندرية سنة 328 م. عُرف بثباته المذهل في الدفاع عن ألوهية المسيح، فنفاه الأباطرة خمس مرات وقضى نحو 17 عاماً في المنفى. كتب العديد من المؤلفات اللاهوتية أشهرها كتاب "تجسد الكلمة". يُلقّب بـ"أثناسيوس ضد العالم" لوقوفه وحده ضد العالم كله في الدفاع عن الإيمان النيقاوي.',
 'كان القرن الرابع مرحلة مفصلية في تاريخ المسيحية. بعد أن أصدر قسطنطين مرسوم ميلانو سنة 313 م الذي أعطى الحرية الدينية، ظهرت بدعة آريوس التي أنكرت ألوهية المسيح وقالت إنه خليقة. انتشرت هذه البدعة بقوة بدعم سياسي من الأباطرة، وكادت أن تعصف بالإيمان المسيحي بأكمله.',
 'كان أثناسيوس هو الصخرة التي تحطمت عليها بدعة آريوس. في مجمع نيقية، صاغ مع غيره مصطلح "homoousios" (المساوٍ في الجوهر) الذي يعلن أن المسيح مساوٍ للآب في الجوهر. رغم نفيه خمس مرات، رفض أبداً قبول أي صيغة إيمان تضع المسيح في مرتبة أدنى من الآب. حفظ بثباته الإيمان النيقاوي للأجيال القادمة. كتب ضد الآريوسيين وأوضح أن الخلاص لا يكون إلا إذا كان المخلص إلهاً حقيقياً.',
 'نفاه الأباطرة خمس مرات: إلى تريفير (335-337)، روما (339-346)، الإسكندرية هارباً (356-362)، الإسكندرية مرة أخرى (365-366)، والإسكندرية (367-368). كاد يُقتل مرات عديدة. وُجهت إليه تهم زائفة في مجمع صور. حُرم من كرسيه ظلماً ورغم براءته.',
 'صياغة مصطلح "المساوٍ في الجوهر" في مجمع نيقية، كتاب "تجسد الكلمة"، كتاب "تاريخ الآريوسيين"، كتاب "عن المجمع"، كتاب "رسائل فصحية"، حفظ الإيمان النيقاوي ضد التيار الآريوسي، تأسيس نظام الرهبنة المصرية مع القديس أنطونيوس.',
 '', '', '')
ON CONFLICT (papal_number) DO NOTHING;

INSERT INTO patriarchs (id, name_ar, name_en, papal_number, birth_date, death_date, papacy_start, papacy_end, century, short_bio_ar, biography_ar, historical_background_ar, faith_defense_ar, challenges_ar, contributions_ar, image_url, image_source, image_credit)
VALUES
('a0000001-0000-0000-0000-000000000003',
 'البابا كيرلس الكبير', 'Pope Cyril I the Great', 24,
 'حوالي 378 م', '27 يونيو 444 م', 'حوالي 412 م', '27 يونيو 444 م', 5,
 'البابا الرابع والعشرون، عمود الدين والمدافع عن طبيعة المسيح الواحدة، رئيس مجمع أفسس المسكوني الثالث.',
 'وُلد كيرلس في بلدة المحمودة قرب الإسكندرية. تربى في دير القديس مقاريوس الكبير. صار شماساً ثم قساً. رافق خاله البابا ثيوفيلوس إلى مجمع القسطنطينية سنة 403 م. اختير بابا للإسكندرية سنة 412 م. في سنة 431 م رأس مجمع أفسس المسكوني الثالث حيث أدان بدعة نسطور التي فصلت بين طبيعتي المسيح. أثبت أن المسيح طبيعة واحدة متجسدة من طبيعتين بلا امتزاج ولا اختلاط. حُبس لفترة بسبب الخلافات السياسية لكنه عاد منتصراً. يُعد من أعظم لاهوتيي الكنيسة القبطية.',
 'كان القرن الخامس عصر صراعات لاهوتية عنيفة حول طبيعة المسيح. ظهر نسطور بطريرك القسطنطينية يعلّم أن المسيح شخصان: شخص إلهي وشخص إنساني، وأن مريم لم تكن والدة الإله بل والدة الإنسان فقط. هذا التعليم كان يهدد أساس الخلاص المسيحي.',
 'وقف كيرلس كالأسد في الدفاع عن أن المسيح طبيعة واحدة متجسدة (Mia Physis) من طبيعتين. رأس مجمع أفسس سنة 431 م وأدان تعليم نسطور. كتب اثنتي عشرة رسالة ضد نسطور أوضح فيها أن اتحاد الكلمة بالجسد اتحاد حقيقي غير قابل للانفصال. صاغ صيغة "طبيعة واحدة متجسدة لله الكلمة" التي أصبحت صيغة إيمان الكنيسة القبطية. أكد أن العذراء مريم هي والدة الإله (Theotokos).',
 'واجه معارضة شديدة من نسطور وأنصاره في القسطنطينية. تعرّض للسجن بأمر من الإمبراطور بسبب الضغوط السياسية. واجه انقساماً داخل الكنيسة بين مؤيديه ومعارضيه. حُرم لفترة ثم أُعيد.',
 'رئاسة مجمع أفسس المسكوني الثالث (431 م)، كتاب "عن التجسد"، كتاب "الكنز المقدس"، اثنتا عشرة رسالة ضد نسطور، صياغة مصطلح "والدة الإله"، تأكيد عقيدة الطبيعة الواحدة المتجسدة.',
 '', '', '')
ON CONFLICT (papal_number) DO NOTHING;

INSERT INTO patriarchs (id, name_ar, name_en, papal_number, birth_date, death_date, papacy_start, papacy_end, century, short_bio_ar, biography_ar, historical_background_ar, faith_defense_ar, challenges_ar, contributions_ar, image_url, image_source, image_credit)
VALUES
('a0000001-0000-0000-0000-000000000004',
 'البابا ديسقوروس الأول', 'Pope Dioscorus I', 25,
 'غير معروف تماماً', 'حوالي 454 م', 'حوالي 444 م', 'حوالي 454 م', 5,
 'البابا الخامس والعشرون، الذي دافع عن الإيمان الأرثوذكسي في مجمع خلقيدونية وثبت على عقيدة الطبيعة الواحدة رغم الاضطهاد.',
 'تولّى ديسقوروس كرسي الإسكندرية بعد وفاة القديس كيرلس الكبير. كان تلميذاً مخلصاً لكيرلس ومدافعاً عن تعاليمه. في سنة 449 م رأس "المجمع اللصوصي" في أفسس الذي برأ أوطيخا. لكن في سنة 451 م، عُقد مجمع خلقيدونية الذي أقر صيغة "طبيعتان بعد الاتحاد" وأدان ديسقوروس ونفاه. رفض ديسقوروس قبول صيغة خلقيدونية معتبراً إياها انحرافاً عن تعليم كيرلس. نُفي إلى غانغرا في آسيا الصغرى حيث تنيّح سنة 454 م. الكنيسة القبطية تعتبره قديساً وشهيداً للإيمان، وأنه حُرم ظلماً لرفضه التخلي عن عقيدة الطبيعة الواحدة المتجسدة.',
 'بعد وفاة كيرلس الكبير، اشتد الصراع اللاهوتي. ظهر أوطيخا الذي بالغ في ردّه على نسطور فقال إن جسد المسيح كان من طبيعة واحدة فقط. عُقد مجمع خلقيدونية سنة 451 م بدوافع سياسية ولاهوتية، وأقر صيغة "طبيعتان بلا اختلاط" التي اعتبرتها الكنيسة القبطية عودة إلى الفكر النسطوري. أدى هذا المجمع إلى الانشقاق الأول بين كنائس الإسكندرية والأنطاكية من جهة، والكنيسة البيزنطية والرومانية من جهة أخرى.',
 'وقف ديسقوروس وحده في مجمع خلقيدونية يدافع عن صيغة كيرلس "طبيعة واحدة متجسدة". رغم التهديد والضغط السياسي من الإمبراطور، رفض قبول الصيغة الخلقيدونية التي كان يعتبرها انحرافاً عن الإيمان الأرثوذكسي. فضل النفي والحرمان على التخلي عن الإيمان الذي تسلّمه من كيرلس. بثباته هذا، حافظت الكنيسة القبطية على عقيدتها حتى اليوم.',
 'نُفي من كرسيه إلى جزيرة غانغرا. حُرم في مجمع خلقيدونية بحكم سياسي أكثر منه لاهوتي. واجه تحالفاً بين البابا الروماني والبطريرك القسطنطيني ضده. عُزل ظلماً وقُرر نفيه. عانى من الوحدة والابتعاد عن كرسيه وكنيسته.',
 'الدفاع عن عقيدة الطبيعة الواحدة المتجسدة في مجمع خلقيدونية، الحفاظ على تعليم كيرلس الكبير، رئاسة مجمع أفسس الثاني (449 م)، الثبات على الإيمان رغم النفي والحرمان.',
 '', '', '')
ON CONFLICT (papal_number) DO NOTHING;

INSERT INTO patriarchs (id, name_ar, name_en, papal_number, birth_date, death_date, papacy_start, papacy_end, century, short_bio_ar, biography_ar, historical_background_ar, faith_defense_ar, challenges_ar, contributions_ar, image_url, image_source, image_credit)
VALUES
('a0000001-0000-0000-0000-000000000005',
 'البابا بنيامين الأول', 'Pope Benjamin I', 38,
 'حوالي 590 م', '3 يناير 661 م', 'حوالي 620 م', '3 يناير 661 م', 7,
 'البابا الثامن والثلاثون، الذي قاد الكنيسة القبطية خلال الفتح الإسلامي لمصر ورغم الاضطهاد البيزنطي الشديد.',
 'وُلد بنيامين في برشوت من ولاية البحيرة. ترهب في دير القديس يوأنس القصير بجبل شيهيت. اختير بابا للإسكندرية حوالي سنة 620 م. في عهده، فرّ من الاضطهاد البيزنطي الذي فرضه هرقل وقبرص بعد مجمع خلقيدونية. اختفى في الصعيد لعدة سنوات. عندما فتح المسلمون مصر بقيادة عمرو بن العاص سنة 641 م، عاد إلى الإسكندرية. عوملت الكنيسة القبطية بفضل من المسلمين بعد أن كانت مضطهدة من البيزنطيين. خدم البابا بنيامين كنيسته بثبات رغم أصعب الظروف.',
 'كانت مصر تحت الحكم البيزنطي الذي اضطهد الأقباط اضطهاداً شديداً بسبب رفضهم لخلقيدونية. فرض الإمبراطور هرقل وكيرلس القسطنطيني صيغة Monotheletism بالقوة. كان الأقباط يُعذَّبون ويُسجنون ويُنفيون. ثم جاء الفتح الإسلامي سنة 641 م الذي غيّر مصير الكنيسة القبطية.',
 'حافظ بنيامين على وحدة الكنيسة القبطية خلال أصعب فترة انتقالية في تاريخها. رغم فراره من الاضطهاد البيزنطي، بقي مرتبطاً بكنيسته وأرشد رعاياه بالرسائل. حفظ الإيمان الأرثوذكسي من محاولات البيزنطيين فرض عقيدة خلقيدونية والمونوثيليتية. تحت الحكم الإسلامي الجديد، تأكدت للكنيسة القبطية حرية العبادة بعد قرون من الاضطهاد.',
 'اضطهاد بيزنطي شديد أدى إلى فراره واختفائه سنوات طويلة في الصعيد. انقسامات داخلية في الكنيسة. دخول قوة سياسية جديدة (الإسلام) إلى مصر وتغيير النظام بأكمله. صعوبة التواصل مع رعيته أثناء الاختفاء.',
 'الحفاظ على وحدة الكنيسة القبطية خلال الفتح الإسلامي، إرشاد الكنيسة في فترة الانتقال من الحكم البيزنطي إلى الإسلامي، إعادة تنظيم الكنيسة بعد عودته للإسكندرية، الحفاظ على الإيمان الأرثوذكسي رغم كل الضغوط.',
 '', '', '')
ON CONFLICT (papal_number) DO NOTHING;
